var rcapD=document.createElement("div");rcapD.id="rcap";document.body.appendChild(rcapD);
var conf=null,rcv2=null,storesC=[];
function otpSend(ph){return KBOTP.start(ph,false).then(function(c){conf=c})}
var _authV=authV,_forgot=forgot;
authV=function(){if(["pin","new","otp","newpin"].indexOf(scr)<0)return _authV();var sv=scr;scr="id";var hero=_authV().split('<div class="ttl">')[0];scr=sv;
var F=function(ic,inner){return '<div class="pin"><span>'+ic+'</span>'+inner+'</div>'},pn=function(id,ph){return F("🔒",'<input id="'+id+'" type="password" inputmode="numeric" maxlength="6" placeholder="'+ph+'">')},C=function(t,f){return '<button class="cta" onclick="'+f+'">'+t+'</button>'},G=function(t,f){return '<button class="cta l" onclick="'+f+'">'+t+'</button>'};
if(scr=="pin")return hero+'<div class="ttl">Welcome <span>back</span></div><div class="mu" style="margin:-8px 0 12px">+91 '+esc(ctx.id)+'</div>'+pn("pn","Enter your password")+C("Login","login()")+G("Login with OTP","loginOtp()")+G("Forgot password?","forgot()")+G("Use another number","scr=\'id\';render(true)");
if(scr=="new")return hero+'<div class="ttl">Create your <span>account</span></div>'+F("👤",'<input id="nm" placeholder="Name" value="'+esc(ctx.nm||"")+'">')+F("+91",'<input id="ph" type="tel" inputmode="numeric" maxlength="10" placeholder="Phone number" value="'+esc(ctx.ph||"")+'">')+pn("p1","Create 6-digit password")+pn("p2","Re-enter password")+C("Get OTP","signup()")+G("Back","scr=\'id\';render(true)");
if(scr=="otp")return hero+'<div class="ttl">Enter <span>OTP</span></div><p class="mu">We sent a 6-digit code to +91 '+esc(ctx.otpPh)+'</p>'+F("🔢",'<input id="otp" type="tel" inputmode="numeric" maxlength="6" placeholder="6-digit OTP">')+C("Verify","otpVerify()")+G("Resend OTP","otpResend()")+G("Back","scr=\'id\';render(true)");
return hero+'<div class="ttl">New <span>password</span></div>'+pn("p1","New 6-digit password")+pn("p2","Re-enter password")+C("Save","setPin()")};
login=async function(){var p=$("#pn").value;if(!/^(\d{4}|\d{6})$/.test(p))return alert("Enter your 6-digit password");try{await auth.signInWithEmailAndPassword(ctx.email,pw(p))}catch(e){alert(e.code=="auth/too-many-requests"?"Too many attempts. Please try again later.":"Wrong password")}};
signup=async function(){var nm=$("#nm").value.trim(),ph=$("#ph").value.replace(/\D/g,"").slice(-10),p=$("#p1").value;if(!nm||ph.length!=10)return alert("Enter your name and a 10-digit mobile number");if(!/^\d{6}$/.test(p)||p!=$("#p2").value)return alert("Enter the same 6-digit password twice");
try{if((await db.collection("lookup").doc(ph).get()).exists)return alert("An account already exists for this number. Please log in.");ctx.reg={nm:nm,ph:ph,p:p};ctx.nm=nm;ctx.ph=ph;ctx.mode="reg";ctx.otpPh=ph;await otpSend(ph);scr="otp";render(true)}catch(e){alert(e.code=="auth/too-many-requests"?"Too many OTP requests. Try again later.":e.message)}};
function otpResend(){otpSend(ctx.otpPh).then(function(){toast("OTP sent again")}).catch(function(e){alert(e.message)})}
loginOtp=async function(){try{var d=await db.collection("lookup").doc(ctx.id).get();if(!d.exists||!d.data().phoneAuth)return alert("OTP login works for accounts created with OTP. Please use your password.");ctx.mode="login";ctx.otpPh=ctx.id;await otpSend(ctx.id);scr="otp";render(true)}catch(e){alert(e.message)}};
forgot=async function(){try{var d=await db.collection("lookup").doc(ctx.id).get();if(d.exists&&d.data().phoneAuth){ctx.mode="forgot";ctx.otpPh=ctx.id;await otpSend(ctx.id);scr="otp";render(true)}else _forgot()}catch(e){alert(e.message)}};
async function otpVerify(){var code=($("#otp").value||"").trim();if(code.length!=6)return alert("Enter the 6-digit OTP");signing=true;try{var u=(await conf.confirm(code)).user,m=ctx.mode;
if(m=="reg"){var r=ctx.reg,em="p"+r.ph+"@kacha.bazaar";await u.linkWithCredential(firebase.auth.EmailAuthProvider.credential(em,pw(r.p)));await u.getIdToken(true);await db.collection("users").doc(u.uid).set({name:r.nm,phone:r.ph,email:em,role:"customer",available:false});await db.collection("lookup").doc(r.ph).set({email:em,uid:u.uid,phoneAuth:true});signing=false;route(u)}
else{var d=await db.collection("lookup").doc(ctx.otpPh).get();if(!d.exists||d.data().uid!==u.uid){signing=false;alert("This number is not linked to an account here.");auth.signOut();return}if(m=="login"){signing=false;route(u)}else{scr="newpin";render(true)}}}catch(e){signing=false;alert(e.code=="auth/invalid-verification-code"?"Wrong OTP":e.message)}}
setPin=async function(){var p=$("#p1").value;if(!/^\d{6}$/.test(p)||p!=$("#p2").value)return alert("Enter the same 6-digit password twice");try{var u=auth.currentUser;await u.updatePassword(pw(p));signing=false;alert("New password has been set");await u.getIdToken(true);route(u)}catch(e){alert(e.message)}};
function nearestStore(lat,lng){var best="",bd=1e12;storesC.forEach(function(s){var p=(s.loc||"").split(",");if(p.length<2||isNaN(+p[0]))return;var d=hv({lat:lat,lng:lng},{lat:+p[0],lng:+p[1]});if(d<bd){bd=d;best=s.id}});return best}
